at-rules.css.css:
@charset "utf-8";
@import url(a.css) screen;
@namespace svg url(http://www.w3.org/2000/svg);
@media (min-width:100px) and (max-width:200px) { a {} }
@supports (display:grid) or (display:flex) { a {} }
@page :first { margin: 1in }
@layer base, components;
@layer base { a {} }
@container card (min-width: 100px) { a {} }
@keyframes x { from { top: 0 } 100% { top: 1px } }

attribute-selectors.css.css:
a[href] {}
a[href="x"] {}
a[href='x' i] {}
a[href~="x{}"] {}
a[data-a="]"] {}

escape-hex.css.css:
.a\2c b { color: red }
.\41 BC { top: 0 }
.\41BC { top: 0 }

escapes.css.css:
a\.b\ c { color: red }
.\31 23 { top: 0 }
a[href="\""] {}
\@media {}

important-variants.css.css:
a {
  a: 1!important;
  b: 2 ! important;
  c: 3 !IMPORTANT;
  d: 4 !/*x*/important;
  e: 5 /*x*/ !important;
  f: 6 important;
  g: 7 !importantx;
}

modern-selectors.css.css:
:is(a, b) :where(.c, .d) { color: red }
a:has(> img) { color: red }
input::placeholder { color: red }
li:nth-child(2n+1 of .x) { color: red }

nesting.css.css:
a {
  color: red;
  & b { color: blue }
  &:hover { color: green }
  @media screen { color: black }
}

no-semicolon-last.css.css:
a { color: red }
b { color: blue;
  top: 0 }

non-ascii.css.css:
/* héllo → wörld */
.класс { content: "日本語"; }
.emoji-\1F600 { content: "😀 x"; }
a::after { content: "→" }

urls.css.css:
a { background: url(foo.png) }
b { background: url( foo.png ) }
c { background: url('foo.png') }
d { background: url("foo.png") }
e { background: url(data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=) }
f { background: url(foo\)bar.png) }
g { background: url(a(b) }

values.css.css:
a {
  grid-template: "a b" 1fr "c d" 2fr / 1fr 2fr;
  font: bold 12px/1.5 "Helvetica Neue", sans-serif;
  transition: all .3s cubic-bezier(.25,.8,.25,1);
  background: linear-gradient(to right, rgba(0,0,0,.5) 0%, #fff 100%);
  content: "a\"b";
  content: 'a\'b';
  width: calc(100% - (2 * var(--x)));
}
